using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Xml.Linq;

namespace TalonAdmin.Soap.TurboSMS
{
    /// <summary>
    /// Client for the TurboSMS SOAP gateway.
    ///
    /// The original was generated by wsdl.exe and derived from
    /// System.Web.Services.Protocols.SoapHttpClientProtocol, which does not exist outside .NET
    /// Framework. This hand-written replacement speaks the same SOAP 1.1 document/literal wrapped
    /// protocol and keeps the original public surface (constructor, Url, CookieContainer, and the
    /// five operations) so call sites did not have to change.
    ///
    /// The operations stay synchronous because the gateway requires Auth and SendSMS to share one
    /// session cookie and the callers invoke them back to back on a background task.
    /// </summary>
    public class Service : IDisposable
    {
        private const string ServiceNamespace = "http://turbosms.in.ua/api/Turbo";
        private static readonly XNamespace Soap = "http://schemas.xmlsoap.org/soap/envelope/";
        private static readonly XNamespace Turbo = ServiceNamespace;

        private readonly HttpClientHandler _handler;
        private readonly HttpClient _client;

        public string Url { get; set; }

        public CookieContainer CookieContainer
        {
            get { return _handler.CookieContainer; }
            set { _handler.CookieContainer = value; }
        }

        public Service()
        {
            Url = "http://turbosms.in.ua/api/soap.html";

            _handler = new HttpClientHandler
            {
                CookieContainer = new CookieContainer(),
                UseCookies = true
            };

            _client = new HttpClient(_handler);
        }

        public string Auth(string login, string password)
        {
            return SingleResult(
                Invoke("Auth", new XElement(Turbo + "login", login), new XElement(Turbo + "password", password)),
                "AuthResult");
        }

        public string GetCreditBalance()
        {
            return SingleResult(Invoke("GetCreditBalance"), "GetCreditBalanceResult");
        }

        public string[] SendSMS(string sender, string destination, string text, string wappush)
        {
            var body = Invoke("SendSMS",
                new XElement(Turbo + "sender", sender),
                new XElement(Turbo + "destination", destination),
                new XElement(Turbo + "text", text),
                new XElement(Turbo + "wappush", wappush));

            return ArrayResult(body, "SendSMSResult");
        }

        public string[] GetNewMessages()
        {
            return ArrayResult(Invoke("GetNewMessages"), "GetNewMessagesResult");
        }

        public string GetMessageStatus(string messageId)
        {
            return SingleResult(
                Invoke("GetMessageStatus", new XElement(Turbo + "MessageId", messageId)),
                "GetMessageStatusResult");
        }

        private XElement Invoke(string operation, params XElement[] parameters)
        {
            var envelope = new XDocument(
                new XElement(Soap + "Envelope",
                    new XAttribute(XNamespace.Xmlns + "soap", Soap.NamespaceName),
                    new XElement(Soap + "Body",
                        new XElement(Turbo + operation, parameters))));

            var request = new HttpRequestMessage(HttpMethod.Post, Url)
            {
                Content = new StringContent(envelope.ToString(), Encoding.UTF8, "text/xml")
            };
            request.Headers.Add("SOAPAction", string.Format("\"{0}/{1}\"", ServiceNamespace, operation));

            using (var response = _client.Send(request))
            {
                var payload = response.Content.ReadAsStringAsync().GetAwaiter().GetResult();

                if (!response.IsSuccessStatusCode)
                {
                    throw new InvalidOperationException(string.Format(
                        "TurboSMS {0} failed with status {1}: {2}",
                        operation, (int)response.StatusCode, payload));
                }

                var document = XDocument.Parse(payload);
                var fault = document.Descendants(Soap + "Fault").FirstOrDefault();
                if (fault != null)
                {
                    var reason = fault.Elements().FirstOrDefault(e => e.Name.LocalName == "faultstring");
                    throw new InvalidOperationException(string.Format(
                        "TurboSMS {0} returned a SOAP fault: {1}",
                        operation, reason == null ? "unknown" : reason.Value));
                }

                return document.Descendants(Soap + "Body").First();
            }
        }

        private static string SingleResult(XElement body, string resultName)
        {
            var result = body.Descendants().FirstOrDefault(e => e.Name.LocalName == resultName);

            return result == null ? null : result.Value;
        }

        private static string[] ArrayResult(XElement body, string resultName)
        {
            var result = body.Descendants().FirstOrDefault(e => e.Name.LocalName == resultName);
            if (result == null)
            {
                return new string[0];
            }

            var items = result.Elements().Select(e => e.Value).ToArray();

            return items.Length > 0 ? items : new[] { result.Value };
        }

        public void Dispose()
        {
            _client.Dispose();
            _handler.Dispose();
        }
    }
}
